const H = height, R = canopy_radius, s = seed, st = style;
const add = (p, sc, k) => { const q = addpoint(0, p); setpointattrib(0, 'scale', q, sc); setpointattrib(0, 'orient', q, quaternion(radians(360 * rand(k, s, 9)), [0, 1, 0])); setpointattrib(0, 'tint', q, 0.82 + 0.3 * rand(k, s, 8)); };
if (st === 'conifer') {
  const n = 4, base = 0.18 * H;
  for (let i = 0; i < n; i++) {
    const t = i / n, r = R * (1 - 0.72 * t), y0 = base + (H - base) * t * 0.78, h = i === n - 1 ? H - y0 : (H - y0) * 0.55;
    add([0, y0, 0], [r, h, r], i);
  }
} else if (st === 'poplar') {
  add([0, H - 0.36 * H, 0], [R * 0.5, 0.36 * H, R * 0.5], 0);
  add([R * 0.18, H * 0.5, R * 0.1], [R * 0.4, 0.2 * H, R * 0.4], 1);
} else {
  const cy = Math.max(H * 0.3, H - R * 0.95) + 0.1 * R;
  add([0, cy, 0], [R * 0.8, R * 0.72, R * 0.8], 0);
  for (let i = 0; i < 5; i++) {
    const a = TAU * (i / 5 + 0.2 * rand(i, s, 1)), d = R * (0.42 + 0.15 * rand(i, s, 2)), r = R * (0.42 + 0.15 * rand(i, s, 3));
    add([Math.cos(a) * d, cy - 0.25 * R + 0.35 * R * rand(i, s, 4), Math.sin(a) * d], [r, r * 0.85, r], i + 1);
  }
}
